import { Command } from 'ckeditor5/src/core';
import { isWidget } from 'ckeditor5/src/widget';

export default class ExpandFileCommand extends Command {
	/**
	 * Executes the command.
	 *
	 *		// Sets the width to 50%:
	 *		editor.execute( 'expandFile', { expanded: true } );
	 *
	 *		// Removes the width attribute / collapses / minimizes:
	*		editor.execute( 'expandFile', { expanded: false } );
	 *
	 * @param {Object} options
	 * @param {String|null} options.expanded The state of the file's expansion
	 * @fires execute
	 */
	execute( ) {
		const selection = this.editor.model.document.selection;
		const editor = this.editor;
		const model = editor.model;
		// const selectedElement = this.getClosestSelectedFileWidget( selection );
		const selectedElement = selection.getSelectedElement();

		if ( selectedElement ) {
			model.change( writer => {
				const currentValue = selectedElement.getAttribute( 'expanded' );
				writer.setAttribute( 'expanded', !currentValue, selectedElement );
			} );
		}
	}

	refresh() {
		this.isEnabled = true;
	}

	isFileWidget( viewElement ) {
		return !!viewElement.name === 'file' && isWidget( viewElement );
	}

	getClosestSelectedFileWidget( selection ) {
		const selectionPosition = selection.getFirstPosition();

		if ( !selectionPosition ) {
			return null;
		}

		const viewElement = selection.getSelectedElement();

		if ( viewElement && this.isFileWidget( viewElement ) ) {
			return viewElement;
		}

		let parent = selectionPosition.parent;

		while ( parent ) {
			if ( parent.is( 'element' ) && this.isFileWidget( parent ) ) {
				return parent;
			}

			parent = parent.parent;
		}

		return null;
	}
}
